"""Small retrying client for the local order service (working script, not a deliverable)."""
import collections
import json
import os
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
MAX_ATTEMPTS = 200


class Api:
    def __init__(self, data_dir):
        os.makedirs(data_dir, exist_ok=True)
        self.token = None
        self.events = open(os.path.join(data_dir, "events.log"), "a", buffering=1)
        self.stats = collections.Counter()
        self.tokens_issued = 0

    def log(self, msg):
        line = time.strftime("%H:%M:%S ") + msg
        self.events.write(line + "\n")
        print(line, flush=True)

    @staticmethod
    def _send(method, path, token):
        data = b"" if method == "POST" else None
        req = urllib.request.Request(BASE + path, data=data, method=method)
        if token:
            req.add_header("Authorization", "Bearer " + token)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, r.headers, r.read()
        except urllib.error.HTTPError as e:
            return e.code, e.headers, e.read()
        except (urllib.error.URLError, OSError) as e:
            return None, {}, repr(e).encode()

    @staticmethod
    def _retry_after(headers, body):
        """Seconds the server asks us to wait, from header or JSON body; None if unknown."""
        h = headers.get("Retry-After") if headers else None
        if h is not None:
            try:
                return float(h)
            except ValueError:
                pass
        try:
            doc = json.loads(body)
        except ValueError:
            return None
        if isinstance(doc, dict):
            for k, v in doc.items():
                if "retry" in k.lower() or "wait" in k.lower():
                    try:
                        return float(v)
                    except (TypeError, ValueError):
                        pass
        return None

    def get_token(self):
        status, doc = self.call("POST", "/token", auth=False)
        self.token = doc["token"]
        self.tokens_issued += 1
        self.log(f"new token {self.token} (issued so far: {self.tokens_issued})")

    def call(self, method, path, auth=True, ok=(200,)):
        """Return (status, parsed_json). Retries until we get an answer in `ok`."""
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if auth and self.token is None:
                self.get_token()
            status, headers, body = self._send(method, path, self.token if auth else None)
            self.stats[status] += 1
            if status in ok:
                try:
                    return status, json.loads(body)
                except ValueError:
                    self.log(f"{method} {path} -> {status} but body is not JSON: {body[:200]!r}; retrying")
                    time.sleep(1)
                    continue
            hdr = {k: v for k, v in (headers.items() if headers else []) if k.lower() in ("retry-after", "www-authenticate", "x-ratelimit-remaining", "x-ratelimit-reset")}
            self.log(f"{method} {path} -> {status} hdr={hdr} body={body[:300]!r} (attempt {attempt})")
            if status == 401 and auth:
                self.token = None
                continue
            if status == 429:
                wait = self._retry_after(headers, body)
                if wait is None:
                    raise RuntimeError(f"429 without a recognisable wait time: {hdr} {body[:300]!r}")
                self.log(f"rate limited; waiting {wait}s as instructed")
                time.sleep(wait)
                continue
            if status is None or status >= 500:
                time.sleep(min(0.25 * 2 ** min(attempt, 5), 5))
                continue
            raise RuntimeError(f"unhandled response {status} for {method} {path}: {body[:300]!r}")
        raise RuntimeError(f"gave up on {method} {path} after {MAX_ATTEMPTS} attempts")

